/**
 * Service worker registration (production builds only; dist/sw.js is generated by vite.config.ts).
 * A new deploy installs in the background and waits; `useUpdateReady` turns true so the UI can offer
 * a reload, which activates the new version (`applyUpdate`).
 */
import { useSyncExternalStore } from 'react';

let waiting: ServiceWorker | null = null;
const listeners = new Set<() => void>();
const setWaiting = (sw: ServiceWorker | null) => { waiting = sw; listeners.forEach((l) => l()); };

export function registerServiceWorker(): void {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  window.addEventListener('load', async () => {
    try {
      const reg = await navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`);
      if (!reg) return;
      // Only an update is worth announcing (no controller = first install).
      const track = (sw: ServiceWorker | null) => {
        if (!sw) return;
        const check = () => { if (sw.state === 'installed' && navigator.serviceWorker.controller) setWaiting(sw); };
        check();
        sw.addEventListener('statechange', check);
      };
      track(reg.waiting ?? reg.installing);
      reg.addEventListener('updatefound', () => track(reg.installing));
      // Long-lived tabs / installed apps: look for a new deploy every hour.
      setInterval(() => { reg.update().catch(() => {}); }, 60 * 60 * 1000);
    } catch (e) {
      console.warn('Service worker registration failed', e);
    }
  });
  // Reload once the new version has taken over - only after the user asked (the first install also
  // fires controllerchange, via clients.claim(), and must not reload the page).
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!updateRequested) return;
    updateRequested = false;
    window.location.reload();
  });
}

let updateRequested = false;

export function applyUpdate(): void {
  if (!waiting) return;
  updateRequested = true;
  waiting.postMessage('SKIP_WAITING');
}

export const useUpdateReady = (): boolean =>
  useSyncExternalStore((l) => { listeners.add(l); return () => listeners.delete(l); }, () => waiting !== null);
